200	\section{Distance measures}
201	
202	\begin{definition}[Distance between states]\label{def:state-distance}
203		Let $\{\ket{\psi_n}\}_{n \in \N}$ and $\{\ket{\psi'_n}\}_{n \in \N}$ be two families of states in the same space $\mathcal H$. For a function $\delta \colon \N \to [0,1]$ we say that $\{\ket{\psi_n}\}$ and $\{\ket{\psi'_n}\}$ are \emph{$\delta$-close}, denoted $\ket{\psi} \approx_\delta \ket{\psi'}$, if
204		\[
205			\lVert \ket{\psi_n} - \ket{\psi'_n} \rVert^2 = O(\delta(n))\,.
206		\]
207		The dependence of the states and of $\delta$ on the indexing parameter $n$ is generally left implicit; we write, e.g., $\ket{\psi}$ for $\ket{\psi_n}$.
208	\end{definition}
209	
210	\begin{definition}[Consistency between POVMs]\label{def:consistency}
211		\lean{MIPStarRE.QPBT.consistencyDefect, MIPStarRE.QPBT.IsConsistentWithin}
212		\leanok
213		\uses{def:povm-conventions, def:state-distance}
214		Let $\mathcal X$ be a finite set and $\mu$ a distribution on $\mathcal X$. Let $\ket{\psi} \in \mathcal H_A \ot \mathcal H_B$ be a quantum state, and for all $x \in \mathcal X$ let $\{A^x_a\}$ and $\{B^x_a\}$ be POVMs. We write
215		\[
216			A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a
217		\]
218		on state $\ket{\psi}$ and distribution $\mu$ if
219		\[
220			\E_{x \sim \mu} \sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi} = O(\delta)\,.
221		\]
222		In this case we say that $\{A^x_a\}$ and $\{B^x_a\}$ are \emph{$\delta$-consistent} on $\ket{\psi}$. As in Definition~\ref{def:state-distance}, the $O(\cdot)$ refers to families of POVMs and states indexed by an implicit parameter $n \in \N$, and is taken as $n \to \infty$.
223	\end{definition}
224	
225	A measurement that is consistent on $\ket{\psi}$ in the sense of Definition~\ref{def:consistent-measurement} is $0$-consistent with itself on the same state under the singleton distribution, and vice versa: if $\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = 1$, then $M_a \ot \Id\, \ket{\psi} = \Id \ot M_a\, \ket{\psi}$ for every $a$, by the equality case of the Cauchy--Schwarz inequality applied outcome by outcome.
226	
227	% The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:257-274) states this
228	% definition for pairs of POVMs but applies the relation to arbitrary operator families:
229	% to plain operators at 06:313-330, to sets of matrices at 06:364-380, and to products and
230	% commutators, compared against the zero family, at 06:409-445. The general form below,
231	% for arbitrary finite families of operators, is the one of the NEEXP source
232	% (references/neexp-paper/05_quantum_preliminaries.tex:385-391), from which the distance
233	% calculus is imported; the POVM case is singled out after the display.
234	\begin{definition}[State-dependent distance between operator families]\label{def:povm-distance}
235		\uses{def:povm-conventions, def:state-distance}
236		Let $\mathcal X$ and $\mathcal A$ be finite sets and $\mu$ a distribution on $\mathcal X$. Let $\ket{\psi} \in \mathcal H$ be a quantum state, and for all $x \in \mathcal X$ let $\{M^x_a\}_{a \in \mathcal A}$ and $\{N^x_a\}_{a \in \mathcal A}$ be two families of linear operators on $\mathcal H$. We say that \emph{$\{M^x_a\}$ and $\{N^x_a\}$ are $\delta$-close on state $\ket{\psi}$ and under distribution $\mu$} if
237		\[
238			\E_{x \sim \mu} \sum_a \lVert (M^x_a - N^x_a)\, \ket{\psi} \rVert^2 \le O(\delta)\,,
239		\]
240		and we write $M^x_a \approx_\delta N^x_a$ to denote this when the state $\ket{\psi}$ and the distribution $\mu$ are clear from context. This distance is referred to as the \emph{state-dependent} distance. The principal case is that in which $\{M^x_a\}$ and $\{N^x_a\}$ are POVMs on $\mathcal H$, and we then speak of the state-dependent distance between the POVMs; but the relation is used for arbitrary operator families --- for instance for products of measurement operators, or for commutators compared against the identically zero family, as in Lemma~\ref{lem:commutation-analysis} below.
241	\end{definition}
